maze_chase.skill_source:
import math

class GeneratedArenaSkill:
    def __init__(self):
        self.t = 0
        self.tx = 0.0
        self.ty = 0.0
        self.stuck = 0
        self.last_x = 0.0
        self.last_y = 0.0

    def compute_action(self, obs):
        self.t += 1
        sx, sy = obs["self"]
        danger = obs.get("danger", 0.0)
        esc = obs.get("escape")
        if danger >= 0.5 and esc is not None:
            ex, ey = esc
            return {"move": [float(ex), float(ey)], "buttons": [], "hold_ms": 0}
        items = obs.get("items") or []
        enemies = obs.get("enemies") or []
        if not items:
            return {"move": [0.0, 0.0], "buttons": [], "hold_ms": 0}
        if abs(sx - self.last_x) < 0.001 and abs(sy - self.last_y) < 0.001:
            self.stuck += 1
        else:
            self.stuck = 0
        self.last_x = sx
        self.last_y = sy
        best = items[0]
        best_d = 1e9
        for i in range(len(items)):
            ix = items[i][0]
            iy = items[i][1]
            d = abs(ix - sx) + abs(iy - sy)
            if d < best_d:
                best_d = d
                best = items[i]
        tx = best[0]
        ty = best[1]
        if self.stuck > 4:
            tx = self.tx
            ty = self.ty
            if self.stuck > 12:
                self.stuck = 0
        else:
            self.tx = tx
            self.ty = ty
        dx = tx - sx
        dy = ty - sy
        adx = dx if dx >= 0 else -dx
        ady = dy if dy >= 0 else -dy
        mvx = 0.0
        mvy = 0.0
        if adx >= ady:
            mvx = 1.0 if dx > 0.01 else -1.0 if dx < -0.01 else 0.0
            if mvx == 0.0:
                mvy = 1.0 if dy > 0 else -1.0 if dy < 0 else 0.0
        else:
            mvy = 1.0 if dy > 0.01 else -1.0 if dy < -0.01 else 0.0
            if mvy == 0.0:
                mvx = 1.0 if dx > 0 else -1.0 if dx < 0 else 0.0
        if len(enemies) > 0:
            ex = enemies[0][0]
            ey = enemies[0][1]
            evx = enemies[0][2]
            evy = enemies[0][3]
            px = ex + evx * 2.0
            py = ey + evy * 2.0
            ddx = px - sx
            ddy = py - sy
            dist = math.sqrt(ddx * ddx + ddy * ddy)
            if dist < 0.12:
                if adx >= ady:
                    if adx > 0.02:
                        mvy = 1.0 if sy < 0.5 else -1.0
                        mvx = 0.0
                else:
                    if ady > 0.02:
                        mvx = 1.0 if sx < 0.5 else -1.0
                        mvy = 0.0
        return {"move": [float(mvx), float(mvy)], "buttons": [], "hold_ms": 0}

key_caves.skill_source:
import math

class GeneratedArenaSkill:
    def __init__(self):
        self.t = 0
        self.d = 1

    def compute_action(self, obs):
        self.t += 1
        sx, sy = obs["self"]
        if obs.get("danger", 0) >= 0.5 and obs.get("escape"):
            ex, ey = obs["escape"]
            return {"move": [ex, ey], "buttons": [], "hold_ms": 0}
        items = obs.get("items") or []
        if items:
            ix, iy = items[0][0], items[0][1]
            mx = 1.0 if ix > sx else -1.0
            if abs(ix - sx) < 0.02:
                mx = 0.0
            my = 1.0 if iy > sy else -1.0
            btn = []
            if abs(ix - sx) < 0.03 and abs(iy - sy) < 0.05:
                btn = [0]
            return {"move": [mx, my], "buttons": btn, "hold_ms": 0}
        if self.t % 120 == 0:
            self.d = -self.d
        mv = float(self.d)
        btns = []
        if self.t % 20 == 0:
            btns = [0]
        if self.t % 40 == 0:
            btns = [2]
        return {"move": [mv, 0.0], "buttons": btns, "hold_ms": 0}
